/**
 * Alt-text golden test (spec-only mode).
 *
 * Parses `templates/template_full.md` (a build artifact of
 * `npm run gen:templates`, regenerated by the pretest hook), generates the
 * auto alt text for every chart block without data, and compares each one
 * to the string stored in `template_full.expected.json`.
 *
 * The golden file is hand-maintained: when alt-text output changes
 * intentionally, regenerate it via `npm run test:bootstrap-alt-text`
 * and verify the diff before committing.
 */
import { describe, it, expect } from "vitest";
import { readFileSync } from "node:fs";
import { generateAltText } from "../../src/modules/alt-text";
import { GOLDEN_SPEC_PATH, loadChartSpecs, type GoldenEntry } from "./helpers";

const chartSpecs = loadChartSpecs();
const golden: GoldenEntry[] = JSON.parse(readFileSync(GOLDEN_SPEC_PATH, "utf8"));

describe("alt-text — template_full.md", () => {
  it("template has the expected number of charts", () => {
    expect(chartSpecs.length).toBe(golden.length);
  });

  chartSpecs.forEach((spec, i) => {
    const label = spec.title ?? `(untitled #${i})`;
    it(`chart ${i}: ${label}`, () => {
      const actual = generateAltText(spec);
      expect(actual).toBe(golden[i]?.alt);
    });
  });
});
